import sqlite3
import os
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET = os.environ.get('HMAC_SECRET', 'default-secret-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        password_hash TEXT NOT NULL
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_session(token):
    """Verify HMAC session token - constant time comparison"""
    if not token:
        return None
    parts = token.split('.')
    if len(parts) != 2:
        return None
    payload, sig = parts
    expected = hmac.new(SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if hmac.compare_digest(sig, expected):
        return payload
    return None

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')
    page = request.args.get('page', '1')

    # Validate field against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    # Validate page is numeric
    if not page.isdigit():
        return jsonify({'error': 'Invalid page number'}), 400

    limit = 20
    offset = (int(page) - 1) * limit

    # Build query with field validated above, value used directly for LIKE
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%' ORDER BY id LIMIT {limit} OFFSET {offset}"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        # Log the search for compliance
        db.execute(
            "INSERT INTO audit_log (action, details) VALUES (?, ?)",
            ('search', f'field={field}, q={value}, results={len(results)}')
        )
        db.commit()
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

    return jsonify({
        'results': [dict(row) for row in results],
        'page': int(page),
        'count': len(results)
    })

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID - requires valid session"""
    token = request.headers.get('X-Session-Token')
    session = verify_session(token)
    if not session:
        return jsonify({'error': 'Unauthorized'}), 401

    db = get_db()
    user = db.execute(
        'SELECT id, username, email, role FROM users WHERE id = ?',
        (user_id,)
    ).fetchone()

    if user is None:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(dict(user))

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.3.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
